package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import java.math.*; import java.time.*; import java.util.*;
@Service public class LoanAdvanceServiceImpl implements LoanAdvanceService{
 private final LoanAdvanceRepository loans; private final LoanRepaymentRepository reps; public LoanAdvanceServiceImpl(LoanAdvanceRepository l,LoanRepaymentRepository r){loans=l;reps=r;}
 public List<LoanAdvance> list(String u,boolean all){return all?loans.findAllByOrderByCreatedAtDesc():loans.findByUserIdOrderByCreatedAtDesc(u);}
 public LoanAdvance create(LoanAdvance x,String u,String n){if(x.getAmount()==null||x.getAmount().signum()<=0)throw new IllegalArgumentException("Amount must be greater than zero."); if(x.getTenureMonths()==null||x.getTenureMonths()<1||x.getTenureMonths()>120)throw new IllegalArgumentException("Tenure must be between 1 and 120 months."); x.setId(null);x.setRequestNumber("LN-"+String.format("%06d",(new Random().nextInt(900000)+100000)));x.setUserId(u);x.setEmployeeName(n);x.setStatus("PENDING");x.setApprovedAmount(null);x.setMonthlyDeduction(null);x.setOutstandingBalance(x.getAmount());return loans.save(x);}
 public LoanAdvance update(Long id,LoanAdvance x,String u){LoanAdvance a=get(id);if(!a.getUserId().equals(u)||!("PENDING".equals(a.getStatus())||"REJECTED".equals(a.getStatus())))throw new IllegalArgumentException("Only your pending/rejected requests can be edited.");a.setType(x.getType());a.setPurpose(x.getPurpose());a.setAmount(x.getAmount());a.setTenureMonths(x.getTenureMonths());return loans.save(a);}
 public LoanAdvance review(Long id,String s,String c,String r){LoanAdvance a=get(id);if(!Set.of("APPROVED","REJECTED").contains(s)||!"PENDING".equals(a.getStatus()))throw new IllegalArgumentException("Only pending requests can be approved or rejected.");a.setStatus(s);a.setReviewer(r);a.setReviewComment(c);if("APPROVED".equals(s)){a.setApprovedAmount(a.getAmount());a.setApprovedDate(LocalDate.now());a.setFirstDeductionDate(LocalDate.now().plusMonths(1));a.setMonthlyDeduction(a.getAmount().divide(BigDecimal.valueOf(a.getTenureMonths()),2,RoundingMode.HALF_UP));a.setOutstandingBalance(a.getApprovedAmount());buildSchedule(a);}return loans.save(a);}
 private void buildSchedule(LoanAdvance a){reps.deleteAll(reps.findByLoanIdOrderByInstallmentNumber(a.getId()));BigDecimal m=a.getMonthlyDeduction(), total=a.getApprovedAmount(); for(int i=1;i<=a.getTenureMonths();i++){LoanRepayment r=new LoanRepayment();r.setLoan(a);r.setInstallmentNumber(i);r.setDueDate(a.getFirstDeductionDate().plusMonths(i-1));r.setAmount(i==a.getTenureMonths()?total.subtract(m.multiply(BigDecimal.valueOf(i-1))):m);r.setStatus("PENDING");reps.save(r);}}
 public List<LoanRepayment> schedule(Long id){get(id);return reps.findByLoanIdOrderByInstallmentNumber(id);}
 public LoanRepayment markPaid(Long id,Long rid){LoanAdvance a=get(id);LoanRepayment r=reps.findById(rid).orElseThrow(()->new IllegalArgumentException("Repayment not found."));if(!Objects.equals(r.getLoan().getId(),id)||!"APPROVED".equals(a.getStatus()))throw new IllegalArgumentException("Invalid repayment.");if(!"PAID".equals(r.getStatus())){r.setStatus("PAID");r.setPaidDate(LocalDate.now());a.setPaidInstallments(a.getPaidInstallments()+1);a.setOutstandingBalance(a.getOutstandingBalance().subtract(r.getAmount()).max(BigDecimal.ZERO));if(a.getOutstandingBalance().signum()==0)a.setStatus("CLOSED");loans.save(a);}return reps.save(r);}
 public void delete(Long id,String u){LoanAdvance a=get(id);if(!a.getUserId().equals(u)||!Set.of("PENDING","REJECTED").contains(a.getStatus()))throw new IllegalArgumentException("Only pending or rejected requests can be deleted.");loans.delete(a);}
 private LoanAdvance get(Long id){return loans.findById(id).orElseThrow(()->new IllegalArgumentException("Loan/advance request not found."));}
}
